 "content": "from collections import Counter


def transform(grid):
    """Fill blank interiors of square frames by outer side-length parity."""
    h, w = len(grid), len(grid[0]) if grid else 0
    out = [row[:] for row in grid]
    if not h or not w:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find complete square frames with blank interiors. Each frame is treated
    # independently; odd outer side lengths map to 7, even lengths to 2.
    for side in range(3, min(h, w) + 1):
        fill = 7 if side % 2 else 2
        for r0 in range(h - side + 1):
            for c0 in range(w - side + 1):
                color = grid[r0][c0]
                if color == background:
                    continue
                if any(grid[r0][c] != color for c in range(c0, c0 + side)):
                    continue
                if any(grid[r0 + side - 1][c] != color for c in range(c0, c0 + side)):
                    continue
                if any(grid[r][c0] != color or grid[r][c0 + side - 1] != color
                       for r in range(r0, r0 + side)):
                    continue
                if any(grid[r][c] != background
                       for r in range(r0 + 1, r0 + side - 1)
                       for c in range(c0 + 1, c0 + side - 1)):
                    continue
                for r in range(r0 + 1, r0 + side - 1):
                    for c in range(c0 + 1, c0 + side - 1):
                        out[r][c] = fill
    return out
